/**
 * `PulseCard(DATA)` from `technical_indicators.returns` -- 1D/1W/1M/3M/6M/1Y price returns,
 * previously fetched and mapped but never rendered anywhere on the Detail screen. Every window
 * shares one glossary entry (`RETURN_WINDOW`) rather than 6 near-duplicate ones, since "return over
 * the stated window" is the same explanation regardless of which window a given stat is.
 *
 * 💡 Its stat holder type is named `ReturnStat` (not the shorter `Stat` `Fundamentals.kt` uses) --
 * a `private` top-level class in Kotlin is only private to the *file* for functions/properties, but
 * still compiles to a single package-visible `.class` file for an actual class, so two files in the
 * same package both naming one `Stat` collide at the JVM level despite the source-level `private`.
 */
@Composable
fun Returns(returns: DomainReturns?, modifier: Modifier = Modifier) {
    if (returns == null) return

    var showGlossary by remember { mutableStateOf(false) }
    val title = stringResource(id = R.string.stock_detail_returns_title)
    val pulseColors = LocalPulseColors.current

    val stats = listOfNotNull(
        returns.d1?.let { stat(R.string.stock_detail_metric_return_1d, it, pulseColors) },
        returns.w1?.let { stat(R.string.stock_detail_metric_return_1w, it, pulseColors) },
        returns.m1?.let { stat(R.string.stock_detail_metric_return_1m, it, pulseColors) },
        returns.m3?.let { stat(R.string.stock_detail_metric_return_3m, it, pulseColors) },
        returns.m6?.let { stat(R.string.stock_detail_metric_return_6m, it, pulseColors) },
        returns.y1?.let { stat(R.string.stock_detail_metric_return_1y, it, pulseColors) }
    )
    if (stats.isEmpty()) return

    PulseCard(style = PulseCardStyle.DATA, modifier = modifier.fillMaxWidth()) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            DataCardTitleWithInfo(title = title, onInfoClick = { showGlossary = true })
            Spacer()

            FlowRow(
                horizontalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_xlarge)),
                verticalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_medium))
            ) {
                stats.forEach { s ->
                    Column(modifier = Modifier.width(dimensionResource(id = R.dimen.detail_stat_width))) {
                        Text(
                            text = s.value,
                            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                            color = s.valueColor
                        )
                        Text(
                            text = stringResource(id = s.labelRes),
                            style = MaterialTheme.typography.labelSmall,
                            color = pulseColors.onSurfaceMuted
                        )
                    }
                }
            }
        }
    }

    if (showGlossary) {
        val entries = stats.map { GlossaryEntry(stringResource(id = it.labelRes), "RETURN_WINDOW") }
        StockAnalysisGlossaryBottomSheet(title = title, entries = entries, onDismiss = { showGlossary = false })
    }
}

private data class ReturnStat(val labelRes: Int, val value: String, val valueColor: Color)

private fun stat(labelRes: Int, rawValue: Double, pulseColors: PulseColors): ReturnStat {
    val color = when {
        rawValue > 0 -> pulseColors.signalBullishText
        rawValue < 0 -> pulseColors.signalBearishText
        else -> pulseColors.signalNeutralText
    }
    val sign = if (rawValue >= 0) "+" else ""
    return ReturnStat(labelRes, "$sign${String.format(Locale.US, "%.2f", rawValue)}%", color)
}

@Composable
private fun Spacer() {
    androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
}

